/**
 * 40 garden & farm hand icons (in hand-icons.ts, 24px grid). Together with the
 * 55 plants they form the pool of things that grow on a done day.
 */
export const FARM_ICONS = [
  'g-shovel', 'g-rake', 'g-hoe', 'g-pitchfork', 'g-watering', 'g-shears', 'g-wheelbarrow', 'g-glove',
  'g-strawhat', 'g-seeds', 'g-hose', 'g-basket', 'g-crate', 'g-hay', 'g-fence', 'g-windmill',
  'g-barn', 'g-tractor', 'g-scarecrow', 'g-bucket', 'g-chicken', 'g-cow', 'g-pig', 'g-sheep',
  'g-duck', 'g-rabbit', 'g-beehive', 'g-eggs', 'g-horseshoe', 'g-coop', 'g-well', 'g-greenhouse',
  'g-silo', 'g-birdhouse', 'g-mailbox', 'g-gate', 'g-ladder', 'g-axe', 'g-milkcan', 'g-vegbed',
] as const

/** Everything that can grow on a done day: "p1".."p55" + the 40 farm icons (95). */
export const GROW_POOL: readonly string[] = [...PLANTS.map(p => `p${p.id}`), ...FARM_ICONS]

/** Small seeded PRNG (xmur3 hash → mulberry32) so picks are the same on every device. */
function rng(seed: string) {
  let h = 1779033703 ^ seed.length
  for (let i = 0; i < seed.length; i++) {
    h = Math.imul(h ^ seed.charCodeAt(i), 3432918353)
    h = (h << 13) | (h >>> 19)
  }
  let a = h >>> 0
  return () => {
    a = (a + 0x6D2B79F5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

/** Share of picks that come from the 55 plants (the rest: the 40 farm icons). */
export const PLANT_SHARE = 0.65
const PLANT_IDS = PLANTS.map(p => `p${p.id}`)

function shuffle(items: readonly string[], next: () => number) {
  const out = [...items]
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(next() * (i + 1))
    ;[out[i], out[j]] = [out[j]!, out[i]!]
  }
  return out
}

const goalPools = new Map<string, string[]>()

/**
 * Icon that grows on day `day` of a goal. The 95 icons are dealt once per goal
 * (seeded by the goal id) as one sequence with no repeats: each step takes the
 * next plant with 65% chance, otherwise the next farm icon (whichever pile is
 * left once the other runs out). The sequence repeats after 95 days.
 */
export function growIconForGoal(goalId: string, day: number) {
  let pool = goalPools.get(goalId)
  if (!pool) {
    const next = rng(goalId)
    const plants = shuffle(PLANT_IDS, next)
    const farm = shuffle(FARM_ICONS, next)
    pool = []
    while (plants.length || farm.length) {
      const fromPlants = farm.length === 0 || (plants.length > 0 && next() < PLANT_SHARE)
      pool.push((fromPlants ? plants : farm).shift()!)
    }
    goalPools.set(goalId, pool)
  }
  return pool[(Math.max(1, Math.floor(day)) - 1) % pool.length]!
}

const baseIconCache = new Map<string, string>()
/** Seeded pick for a date on its own (before the no-repeat rule). */
function baseIconForDate(iso: string) {
  let cached = baseIconCache.get(iso)
  if (cached) return cached
  const next = rng(iso)
  const set = next() < PLANT_SHARE ? PLANT_IDS : FARM_ICONS
  cached = set[Math.floor(next() * set.length)]!
  baseIconCache.set(iso, cached)
  return cached
}

const dayBeforeCache = new Map<string, string>()
function dayBefore(iso: string) {
  let cached = dayBeforeCache.get(iso)
  if (cached) return cached
  const [y, m, d] = iso.split('-').map(Number)
  const t = new Date(Date.UTC(y!, m! - 1, d! - 1))
  cached = t.toISOString().slice(0, 10)
  dayBeforeCache.set(iso, cached)
  return cached
}

const dateIconCache = new Map<string, string>()
/**
 * Icon for a date in the home garden / day page (all goals together), seeded by
 * the date (yyyy-mm-dd): a plant with 65% chance, otherwise a farm icon. It is
 * re-picked when it would match the day before, so neighbours never repeat, and
 * it only depends on the date, so every screen shows the same icon for it.
 */
export function growIconForDate(iso: string): string {
  const cached = dateIconCache.get(iso)
  if (cached) return cached

  const prev = dayBefore(iso)
  const avoid = new Set([baseIconForDate(prev), settledIcon(prev)])
  const next = rng(`${iso}#`)
  let id = baseIconForDate(iso)
  while (avoid.has(id)) {
    const set = next() < PLANT_SHARE ? PLANT_IDS : FARM_ICONS
    id = set[Math.floor(next() * set.length)]!
  }
  dateIconCache.set(iso, id)
  return id
}

const settledIconCache = new Map<string, string>()
/** The icon of `iso` after avoiding the base pick of the day before (one step deep). */
function settledIcon(iso: string) {
  let cached = settledIconCache.get(iso)
  if (cached) return cached

  const prevBase = baseIconForDate(dayBefore(iso))
  const next = rng(`${iso}#`)
  let id = baseIconForDate(iso)
  while (id === prevBase) {
    const set = next() < PLANT_SHARE ? PLANT_IDS : FARM_ICONS
    id = set[Math.floor(next() * set.length)]!
  }
  settledIconCache.set(iso, id)
  return id
}

/** Plant for the n-th day (1-based). Cycles after 55 so long journeys never run out. */
export function plantForDay(day: number) {
  return PLANTS[(Math.max(1, Math.floor(day)) - 1) % PLANTS.length]!
}

export function moodById(id: string | null | undefined) {
  return MOODS.find(m => m.id === id)
}

/** Look up any icon by id: "forest", "p1".."p55" (plants) or "m1".."m5" (moods). */
export function iconById(id: string | null | undefined): GardenIcon | undefined {
  if (!id) return undefined
  if (id === 'forest') return FOREST
  if (id.startsWith('m')) return moodById(id)
  const n = Number(id.replace(/^p/, ''))
  return Number.isInteger(n) && n >= 1 && n <= PLANTS.length ? PLANTS[n - 1] : undefined
}

/** Full standalone SVG string (handy for favicons, native splash assets, etc.). */
export function toSvg(icon: Pick<GardenIcon, 'body'>, size = 32) {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="${VIEWBOX}">${icon.body}</svg>`
}

